import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Log-ratio of recency-weighted past arrivals near each candidate to the uniform expectation, clipped to [-1,1]."""
    k = targets.shape[0]
    if history.shape[0] == 0:
        return np.zeros(k)
    w = np.exp(-(time - history[:, 2]) / 8.0)          # (s,)
    d = targets[:, None, :] - history[None, :, :2]      # (k, s, 2)
    dd = np.sqrt(np.sum(d * d, axis=2))                 # (k, s)
    near = (dd < 0.12).astype(float)                    # (k, s)
    counts = near @ w                                   # (k,)
    expected = w.sum() * np.pi * 0.12 ** 2
    return np.clip(np.log((counts + 0.2) / (expected + 0.2)) / 3.0, -1.0, 1.0)

import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Log ratio of past-arrival density within 0.15 of each candidate to the uniform density, clipped to [-1,1]."""
    k = targets.shape[0]
    if history.shape[0] == 0:
        return np.zeros(k)
    dd = np.linalg.norm(targets[:, None, :] - history[None, :, :2], axis=2)
    counts = (dd < 0.15).sum(axis=1)
    area = np.pi * 0.15 ** 2
    r = (counts + 0.5) / (history.shape[0] * area + 0.5)
    return np.clip(np.log(r) / 2.0, -1.0, 1.0)
